actions.script:
const ids = [].concat(context.runIds || []).flatMap((value) => String(value).split(',')).map((id) => id.trim()).filter(Boolean)
const lib = ec.resource.script('component://tools/template/LoadRuns.js')
const compared = lib.call('compare#LoadRuns', {runIds: ids})
compareError = compared.error
const runs = compared.out.runs || []
runCount = runs.length
const time = (value) => value == null || value === '' ? '' : ec.l10n.format(basicConvert(String(value), 'Timestamp'), 'yyyy-MM-dd HH:mm')
// each run's column: its label, else when it started
runColumns = [0, 1, 2, 3].map((index) => {
    const run = runs[index] || {}
    return {runId: String(run.runId || ''), title: String(run.label || time(run.start) || run.runId || ''),
        caption: [String(run.script || '').replace(/^.*\//, '').replace(/\.load\.js$/, ''), time(run.start), run.status ? String(run.status) : ''].filter(Boolean).join(' · ')}
})
const metrics = {requests: 'Requests', rps: 'Per second', errors: 'Errors', errorRate: 'Error rate', p50: 'p50 (ms)', p95: 'p95 (ms)',
    p99: 'p99 (ms)', count: 'Count'}
const number = lib.number
const shown = (metric, value) => {
    const n = number(value)
    return n == null ? '' : metric == 'errorRate' ? ec.l10n.format(n * 100, '#,##0.##') + '%'
        : ec.l10n.format(n, metric == 'requests' || metric == 'count' || metric == 'errors' ? '#,##0' : '#,##0.##')
}
const change = (value) => { const n = number(value); return n == null ? '' : ' (' + (n > 0 ? '+' : '') + ec.l10n.format(n, '#,##0.#') + '%)' }
let lastGroup = null
compareRows = (compared.out.rows || []).map((row, index) => {
    const group = row.section == 'summary' ? 'Summary' : String(row.name || '')
    const out = {key: String(index), group: group == lastGroup ? '' : group, metric: metrics[row.metric] || String(row.metric || '')}
    lastGroup = group
    const values = row.values || [], changes = row.changes || []
    for (let i = 0; i < 4; i++) out['value' + i] = shown(row.metric, values[i]) + (i > 0 ? change(changes[i]) : '')
    return out
})
